-- How much of a solar system's output a home uses itself, without a battery: MCS MGD 003 look up tables, column "PV only".
-- One row per occupancy type, yearly electricity use band and yearly generation band. Checked 25 Oct 2026.
-- The MCS method covers homes using 1,500 to 5,999 kWh a year and systems making up to 5,999 kWh a year.
CREATE TABLE IF NOT EXISTS self_use_share (
    archetype   text NOT NULL,      -- Home all day | In half the day | Out during the day
    use_from    integer NOT NULL,   -- yearly electricity use band, kWh
    use_to      integer NOT NULL,
    gen_from    integer NOT NULL,   -- yearly generation band, kWh
    gen_to      integer NOT NULL,
    share       numeric NOT NULL,   -- 0 to 1
    source_url  text NOT NULL,
    checked_on  date NOT NULL
);

DELETE FROM self_use_share;

-- The yearly use assumed when the owner has not told us theirs, and how long panels last.
DELETE FROM price_fact WHERE fact_id IN ('typical_elec_use', 'pv_life_years');
